// Writes src/index.ts (generated, not committed): re-exports every element entry and a `define()`
// that registers them all. Run by `build`, `typecheck` and the tests.
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { elementEntries, root } from "./entries.mjs";

const entries = elementEntries();
const lines = [
  "// Generated by scripts/gen-index.mjs from the element folders. Do not edit.",
  'import type { DefineOptions } from "./internal/base.js";',
  ...entries.map((e) => `import { ${e.define} } from "./${e.name}/${e.name}.js";`),
  "",
  'export type { DefineOptions } from "./internal/base.js";',
  ...entries.map((e) => `export * from "./${e.name}/${e.name}.js";`),
  "",
  "/**",
  " * Registers every element under `prefix` (default `ui`). Convenient, but it loads all of them:",
  " * import a single entry (`@jcsoftdev/ui-elements/button`) to pay for one element only.",
  " */",
  "export function define(options?: DefineOptions): void {",
  ...entries.map((e) => `  ${e.define}(options);`),
  "}",
  "",
];
writeFileSync(join(root, "src/index.ts"), lines.join("\n"));
console.log(`gen-index: ${entries.length} elements`);
